import React, { useState, useRef, useEffect } from "react";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import "react-date-range/dist/styles.css";
import "react-date-range/dist/theme/default.css";
import { FaCalendarAlt, FaRegCopy } from "react-icons/fa";
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import Select from "react-select";
import eth from "../Assets/images/ethereum.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import usdt from "../Assets/images/usdt.png";
import { MdRefresh } from "react-icons/md";
import { toast, ToastContainer } from "react-toastify";
import { Spinner } from "react-bootstrap";

const cryptoData = [
  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" }
];


function CryptoAndFiat() {
  const [transakData, setTransakData] = useState([]);
  const [fiatCurrency, setFiatCurrency] = useState("");
  const [cryptoCurrency, setCryptoCurrency] = useState("");
  const [type, setType] = useState("");
  const [status, setStatus] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [selectedCurrency, setSelectedCurrency] = useState(null);
  const [fiatCurrencies, setFiatCurrencies] = useState([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  //console.log("currentPage", currentPage); 
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(false);
  const [limit, setLimit] = useState(10);
  //console.log("limit", limit);

  const [showCalendar, setShowCalendar] = useState(false);
  const [totalItems, setTotalItems] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const calendarRef = useRef(null);

  // console.log('search', search)

  const formatWithoutRounding = (value, decimals) => {
    const factor = Math.pow(10, decimals);
    return Math.floor(value * factor) / factor;
  };

  const userpower = (x) => {
    x = x.toString();

    if (x.includes('e-')) {
      const [num, exp] = x.split('e-');
      const e = parseInt(exp);
      const digits = num.replace('.', '');
      const result = '0.' + '0'.repeat(e - 1) + digits;
      return result;
    } else if (x.includes('e+')) {
      const [num, exp] = x.split('e+');
      const e = parseInt(exp);
      const [intPart, decPart = ''] = num.split('.');
      let fullNum = intPart + decPart;
      while (fullNum.length < intPart.length + e) {
        fullNum += '0';
      }
      const decimal = fullNum.slice(0, intPart.length + e) + '.' + fullNum.slice(intPart.length + e);
      return decimal;
    }

    return x;
  }

  const handleChange = (selectedOption) => {
    handleReset()
    setCryptoCurrency(selectedOption ? selectedOption.value : "");
  };

  const cryptoOptions = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {data.textOne}
      </div>
    ),
  }));

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const getfiatAndcryptohistory = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        fiatCurrency: fiatCurrency?.value || "",
        cryptoCurrency: cryptoCurrency || "",
        type: type || "",
        search: search || "",
        status: status || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
      }).toString();
      let params = {
        url: `user-fiat-crypto-order?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      // console.log(response,"fiat-crypto-response");

      if (response.status) {
        setTransakData(response.data);
        setLoading(false);
        setTotalPages(response.pagination.totalPages);
        setTotalItems(response.pagination.totalItems)
      } else {
        setTransakData([]);
        setLoading(false);
        setTotalPages(0)
        setTotalItems(0)
      }
    } catch (error) {
      console.log("error---", error);
      setLoading(false);
    }
  };

  useEffect(() => {
    setLoading(true)
    getfiatAndcryptohistory(currentPage);
  }, [fiatCurrency, cryptoCurrency, type, search, status, fromDate, toDate, currentPage, limit]);

  const handleClearFilters = async () => {
    setIsRefreshing(true); // Start spinning
    setFiatCurrency("");
    setSelectedCurrency(null);
    setCryptoCurrency("");
    setSearch("");
    setStatus("");
    setType("");
    setFromDate("");
    setToDate("");
    setIs_Refreshing(is_Refreshing ? false : true);
    setRange([
      {
        startDate: new Date(),
        endDate: new Date(),
        key: "selection",
      },
    ]);
    setCurrentPage(1);
    setLimit(10);

    getfiatAndcryptohistory(1);
    const start = Date.now();

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise(resolve => setTimeout(resolve, 500 - elapsed));
    }


    setIsRefreshing(false); // Stop spinning
  };

  useEffect(() => {
    const fetchCurrencies = async () => {
      try {
        const fiatparams = {
          url: `fiat-currencies`,
          method: "GET",
        };
        const fiatRes = await makeApiRequest(fiatparams);

        setFiatCurrencies(fiatRes);
      } catch (error) {
        console.error("Error fetching currencies:", error);
      }
    };
    fetchCurrencies();
  }, [])

  const fiatOptions = fiatCurrencies.map((currency) => ({
    value: currency.symbol,
    label: currency.symbol,
  }));

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("copied to clipboard!");
  };


  const handlefiatCurrency = (selectedOption) => {
    handleReset()
    setFiatCurrency(selectedOption)
    setSelectedCurrency(selectedOption);
    // console.log("Selected currency:", selectedOption.value); 
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.FiatandCryptoOrder.email || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Type",
      selector: (row) => (
        <span className="text-capitalize">{row.isBuyOrSell || "--"}</span>
      ),
      sortable: true,
    },
    {
      name: "Fiat",
      selector: (row) => (
        <span className="text-capitalize">{row.fiatCurrency || "--"}</span>
      ),
      sortable: true,
    },
    {
      name: "Crypto",
      selector: (row) => (
        <span className="text-capitalize">{row.cryptoCurrency || "--"}</span>
      ),
      sortable: true,
    },

    {
      name: "Fiat Amount",
      selector: (row) => row.fiatAmount || "--",
      sortable: true,
      width: "125px",
    },
    {
      name: 'Crypto Amount',
      selector: row => userpower(formatWithoutRounding(userpower(row.cryptoAmount), 8)) || "--",
      sortable: true,
    },
    {
      name: "TotalFees",
      selector: (row) => `${userpower(formatWithoutRounding(userpower(row.totalFeeInFiat), 8))} ${row.fiatCurrency}` || "--",
      sortable: true,
    },

    {
      name: "Order ID",
      selector: (row) => row.orderId || "--",
      cell: (row) => (
        <div className="d-flex ">
          <span className="text-truncate" style={{ maxWidth: "180px" }}>
            {row.orderId || "--"}
          </span>
          {row.orderId && (
            <FaRegCopy
              className="copy-icon"
              style={{ cursor: "pointer" }}
              onClick={() => handleCopy(row.orderId)}
            />
          )}
        </div>
      ),
      sortable: true,
      width: "210px",
    },
    {
      name: "Address",
      selector: (row) => row.walletAddress || "--",
      cell: (row) => (
        <div className="d-flex ">
          <span className="text-truncate" style={{ maxWidth: "180px" }}>
            {row.walletAddress || "--"}
          </span>
          {row.walletAddress && (
            <FaRegCopy
              className="copy-icon"
              style={{ cursor: "pointer" }}
              onClick={() => handleCopy(row.walletAddress)}
            />
          )}
        </div>
      ),
      sortable: true,
      width: "210px",
    },
    {
      name: "Transaction Hash",
      selector: (row) => row.transactionHash || "--",
      cell: (row) => {
        const hasValidHash = row.transactionHash && row.transactionHash !== "--";
        return (
          <div className="d-flex">
            <span className="text-truncate" style={{ maxWidth: "180px" }}>
              {hasValidHash ? row.transactionHash : "--"}
            </span>
            {hasValidHash && (
              <FaRegCopy
                className="copy-icon ms-3"
                style={{ cursor: "pointer" }}
                onClick={() => handleCopy(row.transactionHash)}
              />
            )}
          </div>
        );
      },
      sortable: true,
      width: "210px",
    }
    ,
    // {
    //   name: "Amount",
    //   selector: (row) => row.amountPaid || "--",
    //   sortable: true,
    // },
    {
      name: "Payment Method",
      selector: (row) => row.paymentOptionId || "--",
      sortable: true,
    },

    {
      name: "Status",
      selector: (row) => row.status || "--",
      sortable: true,
    },
    {
      name: "Date(UTC)",
      selector: (row) => dateFormat(row.completedAt || new Date()) || "--",
      sortable: true,
      width: "250px",
    },
  ];

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  }

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    handleReset();
  };

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };

  return (
    <div className="App">
      <ToastContainer />
      <div className="container-fluid " >
        <div className=" text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Crypto and Fiat History
                </h3>
              </div>
              <div className="d-flex calendor-form">
                <form className="d-flex gap-lg-2 align-items-end flex-wrap mb-3">
                  <div>
                    <label for="exampleInputEmail1" className="form-label">
                      Email
                    </label>
                    <input
                      type="text"
                      class="form-control search-bar"
                      id="exampleInputEmail1"
                      aria-describedby="emailHelp"
                      placeholder="Email..."
                      value={search}
                      onChange={handleSearchChange}
                      style={{ width: "220px" }}
                    />
                  </div>
                  <div>
                    <label for="exampleInputPassword1" className="form-label">
                      Fiat
                    </label>
                    <Select
                      options={fiatOptions}
                      value={selectedCurrency}
                      onChange={handlefiatCurrency}
                      placeholder="Select Fiat"
                      isClearable
                      id="border-css"
                      styles={customStyles}
                      isSearchable={false}
                      components={{
                        IndicatorSeparator: () => null,
                      }}
                    />
                  </div>

                  <div>
                    <label for="exampleInputPassword1" className="form-label">
                      Crypto
                    </label>
                    <Select
                      options={cryptoOptions}
                      value={
                        cryptoCurrency
                          ? cryptoOptions.find((option) => option.value === cryptoCurrency)
                          : null
                      }
                      onChange={handleChange}
                      id="border-css"
                      isClearable
                      styles={customStyles}
                      isSearchable={false}
                      components={{
                        IndicatorSeparator: () => null,
                      }}
                    />
                  </div>
                  <div>
                    <label for="exampleInputPassword1" className="form-label">
                      Transaction Status
                    </label>
                    <select
                      className="form-select search-bar"
                      aria-label="Default select example"
                      value={status}
                      onChange={(e) => { setStatus(e.target.value); handleReset() }}
                      style={{ width: "max-content" }}
                    >
                      <option value="">All Status</option>
                      <option value="COMPLETED">Completed</option>
                      <option value="FAILED">Failed</option>
                      <option value="PENDING_DELIVERY_FROM_TRANSAK">Pending</option>
                      <option value="ON_HOLD_PENDING_DELIVERY_FROM_TRANSAK">On-Hold</option>
                      <option value="CANCELLED">Cancelled</option>
                      <option value="EXPIRED">Expired</option>
                    </select>
                  </div>
                  <div>
                    <label for="exampleInputPassword1" className="form-label">
                      Type
                    </label>
                    <select
                      className="form-select search-bar select-coin"
                      aria-label="Default select example"
                      value={type}
                      onChange={(e) => { setType(e.target.value); handleReset() }}
                    >
                      <option value="">All Types</option>
                      <option value="BUY">Buy</option>
                      <option value="SELL">Sell</option>
                    </select>
                  </div>
                  {/* <div class="mb-3">
                                        <label for="exampleInputPassword1" class="form-label">Currency</label>
                                        <select class="form-select" aria-label="Default select example">
                                            <option selected>Open this select menu</option>
                                            <option value="1">One</option>
                                            <option value="2">Two</option>
                                            <option value="3">Three</option>
                                        </select>
                                    </div> */}
                  <div>
                    <label for="exampleInputPassword1" className="form-label">
                      Date
                    </label>

                    <div
                      ref={calendarRef}
                      style={{ position: "relative", width: "max-content" }}
                    >
                      <div
                        onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {fromDate && toDate
                            ? `${fromDate} - ${toDate}`
                            : "Select Date Range"}
                          {/* {range[0].startDate.toLocaleDateString()} - {range[0].endDate.toLocaleDateString()} */}
                        </span>
                        <FaCalendarAlt style={{ color: "#555" }} className="ms-1" />
                      </div>

                      {/* Date range picker (shows when input is clicked) */}
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>
                  <div>
                    <button
                      type="button"
                      className="form-label custom-nav-button-1 active cursor-pointer mb-0"
                      onClick={handleClearFilters}
                      disabled={isRefreshing}
                    >
                      <MdRefresh
                        style={{ fontSize: "24px" }}
                        className={isRefreshing ? "rotate-icon" : ""}
                      />
                    </button>
                  </div>
                </form>
              </div>

              <div className="liquidity-table-1">
                <DataTable
                  key={is_Refreshing}
                  columns={columnsone}
                  data={transakData}
                  theme="solarized"
                  defaultSortAsc={true}
                  pagination
                  paginationServer
                  persistTableHead
                  paginationPerPage={limit}
                  paginationTotalRows={totalItems}
                  paginationRowsPerPageOptions={[5, 10, 15]}
                  paginationResetDefaultPage={resetPaginationToggle}
                  onChangeRowsPerPage={(newRowsPerPage) => {
                    setLimit(newRowsPerPage);
                    setCurrentPage(1);
                  }}
                  onChangePage={(page) => setCurrentPage(page)}
                  progressPending={loading}
                  progressComponent={
                    <div className="py-4 w-100" style={{ marginLeft: "45vw" }}>
                      <Spinner animation="border" />
                    </div>
                  }
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default CryptoAndFiat
